$seed$::jsonb;
  source_type_value text;
  source_reference_value text;
begin
  select id
    into org_id
  from public.oh_organizations
  where slug = 'tucxa'
     or name ilike '%tucxa%'
  order by created_at asc
  limit 1;

  if org_id is null then
    raise exception 'Organização Tucxa não localizada.';
  end if;

  for entry_row in
    select *
    from jsonb_to_recordset(categories_data) as category_row(
      entry_type text,
      name text,
      public_name text,
      slug text,
      group_name text,
      sort_order integer
    )
  loop
    insert into public.oh_financial_categories (
      organization_id,
      entry_type,
      name,
      public_name,
      slug,
      group_name,
      public_visible,
      active,
      sort_order,
      metadata,
      updated_at
    )
    values (
      org_id,
      entry_row.entry_type,
      entry_row.name,
      entry_row.public_name,
      entry_row.slug,
      entry_row.group_name,
      true,
      true,
      entry_row.sort_order,
      jsonb_build_object('origin', 'balancetes_jul_dez_2025'),
      now()
    )
    on conflict (organization_id, entry_type, slug)
    do update set
      name = excluded.name,
      public_name = excluded.public_name,
      group_name = excluded.group_name,
      public_visible = true,
      active = true,
      sort_order = excluded.sort_order,
      metadata = coalesce(oh_financial_categories.metadata, '{}'::jsonb)
        || excluded.metadata,
      updated_at = now();
  end loop;

  -- Os lançamentos consolidados da primeira versão são cancelados para evitar
  -- dupla contagem. Permanecem no banco para fins de auditoria.
  update public.oh_financial_entries
  set
    status = 'cancelado',
    notes_internal = concat_ws(
      E'\n',
      notes_internal,
      'Substituído pelos itens detalhados dos balancetes.'
    ),
    updated_at = now()
  where organization_id = org_id
    and source_type = 'seed_balancete'
    and competence_month between '2025-07-01'::date and '2026-07-01'::date
    and status <> 'cancelado';

  for month_row in
    select *
    from jsonb_to_recordset(seed_data) as month_seed(
      competence_month date,
      opening_balance numeric,
      closing_balance numeric,
      status text,
      needs_update boolean,
      source_label text,
      notes text,
      source_file text,
      rows jsonb
    )
  loop
    insert into public.oh_financial_periods (
      organization_id,
      competence_month,
      status,
      opening_balance,
      closing_balance,
      needs_update,
      source_label,
      notes,
      approved_at,
      updated_at
    )
    values (
      org_id,
      month_row.competence_month,
      month_row.status,
      month_row.opening_balance,
      month_row.closing_balance,
      month_row.needs_update,
      month_row.source_label,
      month_row.notes,
      case
        when month_row.status = 'confirmado' then now()
        else null
      end,
      now()
    )
    on conflict (organization_id, competence_month)
    do update set
      status = excluded.status,
      opening_balance = excluded.opening_balance,
      closing_balance = excluded.closing_balance,
      needs_update = excluded.needs_update,
      source_label = excluded.source_label,
      notes = excluded.notes,
      approved_at = excluded.approved_at,
      updated_at = now()
    returning id into period_id;

    source_type_value := case
      when month_row.status = 'confirmado' then 'balancete_imagem'
      else 'balancete_provisorio'
    end;

    for entry_row in
      select *
      from jsonb_to_recordset(month_row.rows) as balance_entry(
        entry_type text,
        category_slug text,
        amount numeric,
        description_internal text,
        description_public text,
        sort_order integer,
        quantity numeric,
        unit text,
        replicated_from text
      )
    loop
      select id
        into category_id
      from public.oh_financial_categories
      where organization_id = org_id
        and entry_type = entry_row.entry_type
        and slug = entry_row.category_slug
      limit 1;

      if category_id is null then
        raise exception
          'Categoria %/% não localizada.',
          entry_row.entry_type,
          entry_row.category_slug;
      end if;

      source_reference_value := concat(
        source_type_value,
        ':',
        to_char(month_row.competence_month, 'YYYY-MM'),
        ':',
        entry_row.entry_type,
        ':',
        entry_row.category_slug
      );

      insert into public.oh_financial_entries (
        organization_id,
        period_id,
        category_id,
        entry_type,
        entry_date,
        competence_month,
        description_internal,
        description_public,
        amount,
        source_type,
        source_reference,
        status,
        is_provisional,
        needs_update,
        public_visible,
        notes_internal,
        metadata,
        approved_at,
        updated_at
      )
      values (
        org_id,
        period_id,
        category_id,
        entry_row.entry_type,
        (
          date_trunc('month', month_row.competence_month)
          + interval '1 month'
          - interval '1 day'
        )::date,
        month_row.competence_month,
        entry_row.description_internal,
        entry_row.description_public,
        entry_row.amount,
        source_type_value,
        source_reference_value,
        month_row.status,
        month_row.status = 'provisorio',
        month_row.needs_update,
        true,
        case
          when month_row.status = 'provisorio'
            then 'Valor provisório replicado de dezembro de 2025; substituir pelo realizado.'
          else null
        end,
        jsonb_strip_nulls(
          jsonb_build_object(
            'balanceteClientKey',
            concat(
              to_char(month_row.competence_month, 'YYYY-MM'),
              '-',
              entry_row.entry_type,
              '-',
              entry_row.category_slug
            ),
            'sortOrder',
            entry_row.sort_order,
            'quantity',
            entry_row.quantity,
            'unit',
            entry_row.unit,
            'sourceFile',
            month_row.source_file,
            'replicatedFrom',
            entry_row.replicated_from,
            'sourceLabel',
            month_row.source_label
          )
        ),
        case
          when month_row.status = 'confirmado' then now()
          else null
        end,
        now()
      )
      on conflict (organization_id, source_type, source_reference)
      do update set
        period_id = excluded.period_id,
        category_id = excluded.category_id,
        entry_type = excluded.entry_type,
        entry_date = excluded.entry_date,
        competence_month = excluded.competence_month,
        description_internal = excluded.description_internal,
        description_public = excluded.description_public,
        amount = excluded.amount,
        status = excluded.status,
        is_provisional = excluded.is_provisional,
        needs_update = excluded.needs_update,
        public_visible = excluded.public_visible,
        notes_internal = excluded.notes_internal,
        metadata = excluded.metadata,
        approved_at = excluded.approved_at,
        updated_at = now();
    end loop;
  end loop;

  insert into public.oh_financial_audit_logs (
    organization_id,
    action,
    entity_type,
    after_data,
    justification
  )
  values (
    org_id,
    'balancetes_detalhados_importados',
    'oh_financial_periods',
    jsonb_build_object(
      'periodoInicial', '2025-07-01',
      'periodoFinal', '2026-07-01',
      'mesesConfirmados', 6,
      'mesesProvisorios', 7,
      'origem', 'Imagens dos balancetes de julho a dezembro de 2025'
    ),
    'Carga inicial solicitada para o módulo Corrente em Dia.'
  );
end $$;
